"""战役面板 Mixin — 难度选择与进入战役出征准备。"""

from __future__ import annotations

import re
import time
from dataclasses import dataclass
from typing import TYPE_CHECKING

from autowsgr.infra.logger import get_logger
from autowsgr.types import PageName
from autowsgr.ui.map.base import BaseMapPage
from autowsgr.ui.map.data import (
    CAMPAIGN_POSITIONS,
    CAMPAIGN_REMAIN_CROP,
    CLICK_DIFFICULTY,
    DIFFICULTY_EASY_COLOR,
    DIFFICULTY_HARD_COLOR,
    MapPanel,
)
from autowsgr.ui.map.panels.sortie import (
    LOOT_MAX,
    SHIP_MAX,
    recognize_loot_count,
    recognize_ship_count,
)
from autowsgr.ui.substate import SubstateSpec
from autowsgr.ui.utils import wait_for_stable_screen
from autowsgr.vision import PixelChecker


if TYPE_CHECKING:
    import numpy as np


_log = get_logger('ui')


class CampaignPanelMixin(BaseMapPage):
    """Mixin: 战役面板操作 — 难度识别 / 切换 / 进入战役。"""

    # ── 查询 ─────────────────────────────────────────────────────────────

    def get_campaign_remains(self) -> tuple[int, int] | None:
        """获取战役剩余次数。

        Returns
        -------
        tuple[int, int] | None
            返回 (剩余次数, 总次数)，如 (0, 8)。如果识别失败返回 None。
        """
        self.ensure_panel(MapPanel.BATTLE)
        time.sleep(0.5)
        screen = self._ctrl.screenshot()
        img = PixelChecker.crop(screen, *CAMPAIGN_REMAIN_CROP)

        ocr = self._ocr
        if ocr is None:
            _log.warning('[UI] 无法获取战役次数: 未提供 OCR 引擎')
            return None

        results = ocr.recognize(img)
        text = ''.join([r.text for r in results]).replace(' ', '')
        m = re.search(r'(\d+)[/|](\d+)', text)
        if m:
            remains = int(m.group(1))
            total = int(m.group(2))
            _log.info(f'[UI] 战役次数识别成功: {remains}/{total}')
            return remains, total

        _log.warning(f'[UI] 战役次数识别失败: OCR 结果未匹配 ({text})')
        return None

    @staticmethod
    def _difficulty_from_screen(screen: np.ndarray) -> str | None:
        """从单帧截图读取难度；无法判定返回 ``None``。"""
        px = PixelChecker.get_pixel(screen, *CLICK_DIFFICULTY)
        if px.near(DIFFICULTY_EASY_COLOR, tolerance=50):
            return 'hard'
        if px.near(DIFFICULTY_HARD_COLOR, tolerance=50):
            return 'easy'
        return None

    def recognize_difficulty(self) -> str | None:
        """通过检测难度按钮颜色识别当前难度。

        切换图标为蓝色时，说明可以切换为 easy，当前为 hard；反之亦然。

        Returns
        -------
        str | None
            ``"easy"`` / ``"hard"``，识别失败返回 ``None``。

        Raises
        ------
        RuntimeError
            超过重试时限仍无法识别。
        """
        deadline = time.monotonic() + 2.5
        while time.monotonic() < deadline:
            difficulty = self._difficulty_from_screen(self._ctrl.screenshot())
            if difficulty is not None:
                return difficulty
            wait_for_stable_screen(
                self._ctrl,
                timeout=0.3,
                interval=0.1,
                stable_frames=2,
                source='战役难度识别',
                stop_event=self._ctx.stop_event,
            )

        _log.warning('[UI] 无法识别难度: 检测点颜色不匹配简单或困难')
        raise RuntimeError('无法识别战役难度')

    # ── 操作 ─────────────────────────────────────────────────────────────

    def enter_campaign(
        self,
        map_index: int = 2,
        difficulty: str = 'hard',
        campaign_name: str = '未知',
    ) -> None:
        """进入战役: 选择难度和战役类型，直接到达出征准备页面。

        Parameters
        ----------
        map_index:
            战役编号 (1-5: 航母/潜艇/驱逐/巡洋/战列)。
        difficulty:
            难度 ``"easy"`` 或 ``"hard"``。
        campaign_name:
            战役名称 (仅用于日志)。

        Raises
        ------
        ValueError
            战役编号或难度无效。
        NavigationError
            导航超时。
        """
        from autowsgr.ui.battle.preparation import BattlePreparationPage

        if map_index not in CAMPAIGN_POSITIONS:
            raise ValueError(f'战役编号必须为 1-5，收到: {map_index}')
        if difficulty not in ('easy', 'hard'):
            raise ValueError(f'难度必须为 easy 或 hard，收到: {difficulty}')

        _log.info(
            '[UI] 地图页面 → 进入战役 {} ({})',
            campaign_name,
            difficulty,
        )

        # 1. 切换到战役面板
        self.ensure_panel(MapPanel.BATTLE)

        # 2. 选择难度：点击后用颜色 checker 验证，而不是固定 sleep。
        difficulty_spec = SubstateSpec(
            page=PageName.MAP.value,
            substate=f'战役/难度{difficulty}',
            checker=lambda screen: self._difficulty_from_screen(screen) == difficulty,
            timeout=2.0,
            retries=1,
            interval=0.2,
            stable_frames=2,
            probe=lambda screen: self._difficulty_from_screen(screen) is not None,
        )
        if self.recognize_difficulty() != difficulty:
            difficulty_spec.click(
                self._ctx,
                CLICK_DIFFICULTY,
                source='地图-战役难度',
                action_name='toggle_campaign_difficulty',
            )
            # 难度按钮切换后仍可能有短动画；等稳定帧再点战役卡片。
            wait_for_stable_screen(
                self._ctrl,
                timeout=0.8,
                interval=0.12,
                stable_frames=2,
                source='战役难度切换后',
                stop_event=self._ctx.stop_event,
            )
        else:
            difficulty_spec.wait(self._ctx, source='地图-战役难度')

        # 3. 选择战役并验证到达出征准备页
        SubstateSpec(
            page=PageName.BATTLE_PREP.value,
            substate=f'战役/{campaign_name}',
            checker=BattlePreparationPage.is_current_page,
            timeout=5.0,
            retries=2,
            interval=0.35,
            stable_frames=2,
        ).click(
            self._ctx,
            CAMPAIGN_POSITIONS[map_index],
            source=f'地图-战役 {campaign_name}',
            action_name='enter_campaign',
        )

    # ── 今日获取数量 ──────────────────────────────────────────────────────

    @dataclass
    class AcquisitionCounts:
        """今日获取数量。"""

        ship_count: int | None = None
        """今日已获取舰船数量。"""
        ship_max: int = SHIP_MAX
        """今日舰船获取上限。"""
        loot_count: int | None = None
        """今日已获取战利品数量。"""
        loot_max: int = LOOT_MAX
        """今日战利品获取上限。"""

    def _recognize_acquisition_counts(
        self,
        screen: np.ndarray,
    ) -> AcquisitionCounts:
        """从截图中 OCR 识别今日舰船与战利品获取数量。

        Parameters
        ----------
        screen:
            当前截图 (numpy 数组)。

        Returns
        -------
        AcquisitionCounts
            识别到的数量信息, 无法识别的字段为 ``None``。
        """
        result = self.AcquisitionCounts()
        ocr = self._ocr
        if ocr is None:
            _log.warning('[UI] 未提供 OCR 引擎，无法识别获取数量')
            return result

        result.loot_count = recognize_loot_count(screen, ocr)
        result.ship_count = recognize_ship_count(screen, ocr)
        return result

    def get_acquisition_counts(self) -> AcquisitionCounts:
        """获取今日舰船与战利品获取数量。

        自动确保当前位于出征面板，然后截图并执行 OCR 识别。

        Returns
        -------
        AcquisitionCounts
            识别到的数量信息。
        """
        self.ensure_panel(MapPanel.SORTIE)
        time.sleep(0.5)
        screen = self._ctrl.screenshot()
        return self._recognize_acquisition_counts(screen)
